      frame.srcdoc=OpeningHTML;
      const own=frame,ownToken=tokenFor(row);frame.addEventListener('load',()=>{if(frame!==own||disposed)return;try{bindFrame(own,row,false);}catch(e){warn('标题页桥接失败：'+e.message);}});
